def debug_transform(grid):
    h_row = -1
    max_colored = 0
    for r in range(len(grid)):
        colored = sum(1 for c in grid[r] if c != 0)
        if colored > max_colored:
            max_colored = colored
            h_row = r

    # Find vertical lines (cols that have colored cells below h_row)
    vertical_cols = []
    for c in range(len(grid[0])):
        below_colors = [grid[r][c] for r in range(h_row+1, len(grid)) if grid[r][c] != 0]
        if below_colors:
            vertical_cols.append(c)

    print(f"Step 1 - Input horizontal row {h_row}: {grid[h_row]}")
    print(f"Vertical cols: {vertical_cols}")

    result = [[0]*len(grid[0]) for _ in range(len(grid))]

    # STEP 1: Fill horizontal line - what should each cell be?
    print(f"\nStep 2 - Filling horizontal:")
    h_row_pattern = grid[h_row][:]
    for c, val in enumerate(grid[h_row]):
        if val == 0:
            # Find nearest non-zero
            left_nearest = None
            for left_c in range(c-1, -1, -1):
                if grid[h_row][left_c] != 0:
                    left_nearest = grid[h_row][left_c]
                    break

            right_nearest = None
            for right_c in range(c+1, len(grid[0])):
                if grid[h_row][right_c] != 0:
                    right_nearest = grid[h_row][right_c]
                    break

            # Use nearest non-zero
            fill_val = left_nearest if left_nearest is not None else right_nearest
            print(f"  Cell {c}: gap 0 -> nearest {fill_val} (left={left_nearest}, right={right_nearest})")
        h_row_pattern[c] = val

    print(f"Filled horizontal: {h_row_pattern}")

    # STEP 2: Build result
    print(f"\nStep 3 - Building result:")
    for c in range(len(grid[0])):
        result[h_row][c] = grid[h_row][c]  # First copy the input - then we'll overwrite

    for c in range(len(grid[0])):
        if grid[h_row][c] != 0:
            result[h_row][c] = grid[h_row][c]
        else:
            # Fill gap
            left_nearest = None
            for left_c in range(c-1, -1, -1):
                if grid[h_row][left_c] != 0:
                    left_nearest = grid[h_row][left_c]
                    break

            right_nearest = None
            for right_c in range(c+1, len(grid[0])):
                if grid[h_row][right_c] != 0:
                    right_nearest = grid[h_row][right_c]
                    break

            fill_val = left_nearest if left_nearest is not None else right_nearest
            result[h_row][c] = fill_val

    print(f"Result row {h_row}: {result[h_row]}")

    # STEP 3: Vertical above gets filled horizontal color
    print(f"\nStep 4 - Vertical upward:")
    for c in vertical_cols:
        for r in range(h_row):
            result[r][c] = result[h_row][c]  # Filled horizontal color

    for r in range(5):  # Just rows 0-4
        print(f"  Row {r}, Col 3: {result[r][3]}, Col 9: {result[r][9]}")

    print(f"\nFinal result:")
    for r in range(15):
        print(' '.join(map(str, result[r])))

    print(f"\nExpected:")
    for r in range(15):
        print(' '.join(map(str, dp1_out[r])))

    return result

